package com.hbm.entity.projectile;
import com.hbm.entity.mob.maskman.*;import com.hbm.damage.HbmDamageSources;import com.hbm.damage.mixin.LivingDamageAccess;import com.hbm.weapon.sedna.ShotSensitiveBlock;import com.hbm.explosion.vanillant.*;import com.hbm.explosion.vanillant.standard.*;import net.minecraft.core.*;import net.minecraft.core.particles.*;import net.minecraft.core.registries.Registries;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.*;import net.minecraft.resources.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.*;import net.minecraft.util.Mth;import net.minecraft.world.damagesource.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;
/** Real retired NT execution for the migrated MaskMan/BOTPrime/UFO NPC configurations. Source interpolation/penetration/ricochet/VNT/callback ordering preserved; no MK4 substitution. */
public final class EntityBulletBaseNT extends EntityThrowableInterp implements com.hbm.entity.LegacyTrackingRange,com.hbm.explosion.ExplosionNuclearExempt {
 private static final EntityDataAccessor<Integer> CONFIG=SynchedEntityData.defineId(EntityBulletBaseNT.class,EntityDataSerializers.INT);public float overrideDamage;public static java.util.function.Consumer<EntityBulletBaseNT> CLIENT_BEFORE_UPDATE=bullet->{},CLIENT_UPDATE=bullet->{};
 public EntityBulletBaseNT(EntityType<? extends EntityBulletBaseNT> type,Level world){super(type,world);}
 public EntityBulletBaseNT(Level world,LegacyNpcBullets config){this(MaskManContent.NT_BULLET.get(),world);entityData.set(CONFIG,config.sourceId);}
 public EntityBulletBaseNT(Level world,LegacyNpcBullets config,LivingEntity owner,LivingEntity target,float motion,float deviation){this(world,config);setThrower(owner);double y=owner.getY()+owner.getEyeHeight()-.10000000149011612D,dx=target.getX()-owner.getX(),dy=target.getBoundingBox().minY+target.getBbHeight()/3F-y,dz=target.getZ()-owner.getZ(),horizontal=(float)Math.sqrt(dx*dx+dz*dz);setPos(0,y,0);if(horizontal>=1.0E-7D){moveTo(owner.getX()+dx/horizontal,y,owner.getZ()+dz/horizontal,(float)(Math.atan2(dz,dx)*180/Math.PI)-90,(float)-(Math.atan2(dy,horizontal)*180/Math.PI));setThrowableHeading(dx,dy,dz,motion,deviation);}}
 public LegacyNpcBullets config(){return LegacyNpcBullets.byId(entityData.get(CONFIG));}@Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(CONFIG,0);}@Override public int legacyTrackingRange(){return 250;}
 @Override public void tick(){var cfg=config();if(cfg==null){discard();return;}if(!level().isClientSide&&tickCount>cfg.life)discard();if(cfg==LegacyNpcBullets.ORB&&!level().isClientSide&&tickCount%10==5){for(var player:level().getEntitiesOfClass(Player.class,getBoundingBox().inflate(50))){var motion=new Vec3(player.getX()-getX(),player.getEyeY()-getY(),player.getZ()-getZ()).normalize();var bolt=new EntityBulletBaseNT(level(),LegacyNpcBullets.BOLT);bolt.setThrower(getThrower());bolt.setPos(position());bolt.setThrowableHeading(motion.x,motion.y,motion.z,.5F,.05F);level().addFreshEntity(bolt);}}if(cfg==LegacyNpcBullets.UFO_ROCKET)com.hbm.entity.mob.ufo.UfoRocketBehavior.update(this);if(level().isClientSide)CLIENT_BEFORE_UPDATE.accept(this);xo=getX();yo=getY();zo=getZ();super.tick();if(level().isClientSide)CLIENT_UPDATE.accept(this);}
 @Override protected void onImpact(HitResult hit){var cfg=config();if(cfg==null)return;if(hit instanceof BlockHitResult block){boolean higher=random.nextInt(100)<cfg.higherChance,ricochet=cfg.ricochet&&higher;if(!ricochet){setPos(hit.getLocation());blockImpact(block.getBlockPos(),block.getDirection().get3DDataValue());}if(ricochet){var m=getDeltaMovement();random.nextInt(100); // Original LBRC draw still occurs even though higher=true short-circuits its condition.
 switch(block.getDirection().getAxis()){case X->m=new Vec3(-m.x,m.y,m.z);case Y->m=new Vec3(m.x,-m.y,m.z);case Z->m=new Vec3(m.x,m.y,-m.z);}if(cfg.style==4)level().playSound(null,getX(),getY(),getZ(),com.hbm.registry.HbmSounds.get("weapon.ricochet"),SoundSource.NEUTRAL,.25F,1);else if(cfg==LegacyNpcBullets.UFO_ROCKET)level().playSound(null,getX(),getY(),getZ(),com.hbm.registry.HbmSounds.get("weapon.gBounce"),SoundSource.NEUTRAL,1,1);setPos(hit.getLocation());setDeltaMovement(m.scale(cfg.bounce));}}
 if(hit instanceof EntityHitResult entityHit){var victim=entityHit.getEntity();var source=cfg.laser?laserDamage():HbmDamageSources.causeBulletDamage(this,getThrower());if(!cfg.penetrate){setPos(hit.getLocation());entityHurt(victim);blockImpact(new BlockPos(-1,-1,-1),-1);}else entityHurt(victim);float damage=random.nextFloat()*(cfg.maxDamage-cfg.minDamage)+cfg.minDamage;if(overrideDamage!=0)damage=overrideDamage;if(!victim.hurt(source,damage)&&victim instanceof LivingDamageAccess access)victim.hurt(source,damage+access.hbm$getLastHurt());}}
 private DamageSource laserDamage(){var key=ResourceKey.create(Registries.DAMAGE_TYPE,ResourceLocation.parse("hbm:maskman_laser"));return new DamageSource(level().registryAccess().registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(key),this,getThrower());}
 private void entityHurt(Entity entity){if(config().incendiary>0&&!level().isClientSide)entity.igniteForSeconds(config().incendiary);}
 private void blockImpact(BlockPos pos,int side){var cfg=config();var state=side>=0?level().getBlockState(pos):Blocks.AIR.defaultBlockState();if(cfg==LegacyNpcBullets.UFO_ROCKET)com.hbm.entity.mob.ufo.UfoRocketBehavior.impact(this);if(cfg==LegacyNpcBullets.TRACER&&!level().isClientSide){var meteor=new EntityBulletBaseNT(level(),LegacyNpcBullets.METEOR);meteor.setPos(getX(),getY()+30+level().random.nextInt(10),getZ());meteor.setDeltaMovement(0,-1,0);meteor.setThrower(getThrower());level().addFreshEntity(meteor);}if(!level().isClientSide){if(side>=0&&!inGround)discard();if(!cfg.penetrate&&side<0)discard();if(cfg.incendiary>0){int x=(int)getX(),y=(int)getY(),z=(int)getZ();for(var fire:new BlockPos[]{new BlockPos(x,y,z),new BlockPos(x+1,y,z),new BlockPos(x-1,y,z),new BlockPos(x,y+1,z),new BlockPos(x,y-1,z),new BlockPos(x,y,z+1),new BlockPos(x,y,z-1)})if(level().random.nextInt(3)==0&&level().isEmptyBlock(fire))level().setBlockAndUpdate(fire,Blocks.FIRE.defaultBlockState());}if(cfg.explosive>0){var explosion=new ExplosionVNT(level(),getX(),getY(),getZ(),cfg.explosive,getThrower()).setBlockAllocator(new BlockAllocatorStandard()).setBlockProcessor(cfg.blockDamage?new BlockProcessorStandard().withBlockEffect(cfg.incendiary>0?new BlockMutatorFire():null):new MaskManNoBlockDamage().withBlockEffect(cfg.incendiary>0?new BlockMutatorFire():null)).setEntityProcessor(new EntityProcessorStandard().allowSelfDamage()).setPlayerProcessor(new PlayerProcessorStandard()).setSFX(new ExplosionEffectStandard());explosion.explode();}if(cfg==LegacyNpcBullets.TURBINE&&side>=0){if(state.getDestroySpeed(level(),pos)<=120)level().destroyBlock(pos,false);}else if(cfg.breakGlass){var block=state.getBlock();if(block==Blocks.GLASS||block==Blocks.GLASS_PANE||block instanceof StainedGlassBlock||block instanceof StainedGlassPaneBlock)level().destroyBlock(pos,false);if(block instanceof ShotSensitiveBlock sensitive)sensitive.onShot(level(),pos);}}}
 @Override public boolean doesPenetrate(){return config()!=null&&config().penetrate;}@Override protected double headingForceMult(){return 1;}@Override public double getGravityVelocity(){return config()==null?0:config().gravity;}@Override protected double motionMult(){return config()==null?0:config().velocity;}@Override protected float getAirDrag(){return 1;}@Override protected float getWaterDrag(){return 1;}@Override public boolean shouldRenderAtSqrDistance(double d){double size=getBoundingBox().getSize()*4*64*10;return d<size*size;}@Override public boolean shouldBeSaved(){return false;}@Override protected void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);discard();}
}
